using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

public class AstriumActivatedOmenData : OmenData
{
	[Header("Astrium Activated Omen")]
	[SerializeField]
	protected AstriumEffect astriumEffect;

	[NonSerialized]
	private Action omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = GetOmenAction(omenInstance);
		ReferenceSingleton<OrionOmensHandler>.Instance.AstriumActivatedOmenActions.Add(omenAction);
	}

	protected virtual Action GetOmenAction(OmenInstance omenInstance)
	{
		return null;
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<OrionOmensHandler>.Instance.AstriumActivatedOmenActions.Remove(omenAction);
	}

	public override string OmenConvertedDescription()
	{
		string arg = base.OmenConvertedDescription();
		return Smart.Format(base.localizationManager.GetLocalizedWhenTriggered(), astriumEffect.GetEffectName(), arg);
	}
}
